import {
  MapContainer,
  TileLayer,
  ZoomControl,
  Marker,
  useMapEvents,
} from 'react-leaflet';
import L from 'leaflet';

type Category =
  | 'architecture'
  | 'restaurants'
  | 'parks'
  | 'medicine'
  | 'products'
  | 'shopping'
  | 'leisure'
  | 'hotels'
  | 'entertainment'
  | 'coffee'
  | 'beach'
  | 'beauty';

type Point = {
  id: number;
  name: string;
  description: string;
  lat: number;
  lng: number;
  category: Category;
  type?: string;
  address?: string;
};

function createIcon(
  iconUrl: string,
  iconSize: [number, number],
  iconAnchor: [number, number]
) {
  return L.icon({
    iconUrl,
    iconSize,
    iconAnchor,
    popupAnchor: [0, -iconSize[1] + 10],
  });
}

function ZoomHandler({
  onZoomChange,
}: {
  onZoomChange: (zoom: number) => void;
}) {
  const map = useMapEvents({
    zoomend: () => {
      onZoomChange(map.getZoom());
    },
  });

  return null;
}

